{
  "plan": {
    "overview": "Preparing for a job interview involves several steps to help you feel confident and prepared. This plan outlines the key steps to take to ensure you make a positive impression and showcase your skills and qualifications.",
    "rationale": "A well-prepared interview can make a significant difference in your chances of getting hired. By following this plan, you can demonstrate your enthusiasm and commitment to the role, and increase your chances of success."
  },
  "steps": [
    {
